package com.cloudinfra.sdk

import scala.concurrent.{Future, ExecutionContext}
import scala.sys.process._
import java.security.MessageDigest
import java.nio.charset.StandardCharsets

object ResourceNaming {
  private val ALLOWED_CHARS = "[a-zA-Z0-9._-]"
  private val MAX_LENGTH = 63

  def sanitizeLabel(input: String): String = {
    input.filter(c => c.isLetterOrDigit || c == '.' || c == '_' || c == '-')
         .take(MAX_LENGTH)
  }

  def computeHash(value: String): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    val hash = digest.digest(value.getBytes(StandardCharsets.UTF_8))
    hash.map("%02x".format(_)).mkString.take(12)
  }
}

trait ShellExecutor {
  def execute(command: Seq[String])(implicit ec: ExecutionContext): Future[String]
}

class SecureShellExecutor extends ShellExecutor {
  override def execute(command: Seq[String])(implicit ec: ExecutionContext): Future[String] = {
    Future {
      val process = Process(command)
      process.!!
    }
  }
}

case class VolumeConfig(
  name: String,
  region: String,
  sizeGb: Int,
  tags: Map[String, String] = Map.empty
)

class StorageProvisioner(executor: ShellExecutor)(implicit ec: ExecutionContext) {

  private def buildVolumeIdentifier(config: VolumeConfig): String = {
    val sanitizedName = ResourceNaming.sanitizeLabel(config.name)
    val regionPrefix = ResourceNaming.sanitizeLabel(config.region)
    s"${regionPrefix}/${sanitizedName}"
  }

  private def buildTagArguments(tags: Map[String, String]): Seq[String] = {
    tags.flatMap { case (k, v) =>
      val safeKey = ResourceNaming.sanitizeLabel(k)
      val safeValue = ResourceNaming.sanitizeLabel(v)
      Seq("--tag", s"${safeKey}=${safeValue}")
    }.toSeq
  }

  def provisionVolume(config: VolumeConfig): Future[String] = {
    val volumeId = buildVolumeIdentifier(config)
    val baseCmd = Seq("cloud-cli", "storage", "create",
      "--name", volumeId,
      "--size", config.sizeGb.toString)
    val tagArgs = buildTagArguments(config.tags)
    executor.execute(baseCmd ++ tagArgs)
  }

  def snapshotVolume(volumeId: String, label: String): Future[String] = {
    val safeLabel = ResourceNaming.sanitizeLabel(label)
    val cmd = Seq("cloud-cli", "storage", "snapshot",
      "--volume", volumeId,
      "--label", safeLabel)
    executor.execute(cmd)
  }
}

class InfraOrchestrator(provisioner: StorageProvisioner)(implicit ec: ExecutionContext) {

  private var provisionedVolumes: Map[String, VolumeConfig] = Map.empty

  def deployStack(configs: Seq[VolumeConfig]): Future[Seq[String]] = {
    val futures = configs.map { config =>
      provisioner.provisionVolume(config).map { result =>
        synchronized {
          provisionedVolumes += (result -> config)
        }
        result
      }
    }
    Future.sequence(futures)
  }

  def createSnapshots(snapshotLabel: String): Future[Seq[String]] = {
    val volumes = synchronized { provisionedVolumes.toSeq }
    val futures = volumes.map { case (volumeId, _) =>
      provisioner.snapshotVolume(volumeId, snapshotLabel)
    }
    Future.sequence(futures)
  }
}

class MigrationService(executor: ShellExecutor)(implicit ec: ExecutionContext) {

  private def resolveSourcePath(region: String, volumeName: String): String = {
    val safeRegion = ResourceNaming.sanitizeLabel(region)
    val safeName = ResourceNaming.sanitizeLabel(volumeName)
    s"/mnt/volumes/${safeRegion}/${safeName}"
  }

  def migrateVolume(sourceRegion: String, targetRegion: String, 
                    volumeName: String, encryptionKey: String): Future[String] = {
    val sourcePath = resolveSourcePath(sourceRegion, volumeName)
    val targetPath = resolveSourcePath(targetRegion, volumeName)
    val keyHash = ResourceNaming.computeHash(encryptionKey)

    // The encryption key hash is used as a transfer session identifier
    val transferCmd = Seq("cloud-cli", "transfer", "--source", sourcePath, "--target", targetPath, "--session", keyHash)

    executor.execute(transferCmd)
  }
}

object CloudInfraApp extends App {
  implicit val ec: ExecutionContext = ExecutionContext.global

  val executor = new SecureShellExecutor()
  val provisioner = new StorageProvisioner(executor)
  val orchestrator = new InfraOrchestrator(provisioner)
  val migration = new MigrationService(executor)
}
